insert into public.diagnostic_questions(id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,active) select id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,true from jsonb_to_recordset($diagnostic$[{"id":"db-1-16","category":"database_technical","subcategory":"Constraints","question_text":"Which constraint limits values using a Boolean condition?","options":["DEFAULT","INDEX","VIEW","CHECK"],"correct_answer":"D","explanation":"CHECK validates a predicate for inserted or updated rows.","estimated_time_seconds":60,"difficulty":2,"option_a":"DEFAULT","option_b":"INDEX","option_c":"VIEW","option_d":"CHECK"},{"id":"db-1-17","category":"database_technical","subcategory":"Views","question_text":"A standard database view primarily stores what?","options":["A query definition","A copy of every result row","An index only","Transaction logs"],"correct_answer":"A","explanation":"A normal view stores its defining query, unlike a materialized view.","estimated_time_seconds":60,"difficulty":2,"option_a":"A query definition","option_b":"A copy of every result row","option_c":"An index only","option_d":"Transaction logs"},{"id":"db-1-18","category":"database_technical","subcategory":"Normalization","question_text":"A transitive dependency of a non-key attribute violates which normal form?","options":["First normal form","Third normal form","Second normal form only","Domain-key normal form only"],"correct_answer":"B","explanation":"3NF removes transitive dependencies on candidate keys.","estimated_time_seconds":60,"difficulty":3,"option_a":"First normal form","option_b":"Third normal form","option_c":"Second normal form only","option_d":"Domain-key normal form only"},{"id":"db-1-19","category":"database_technical","subcategory":"Joins","question_text":"What does an INNER JOIN return?","options":["Every left row","Every possible pair only","Rows satisfying the join condition in both inputs","Only unmatched rows"],"correct_answer":"C","explanation":"INNER JOIN retains matching combinations.","estimated_time_seconds":60,"difficulty":3,"option_a":"Every left row","option_b":"Every possible pair only","option_c":"Rows satisfying the join condition in both inputs","option_d":"Only unmatched rows"},{"id":"db-1-20","category":"database_technical","subcategory":"Ordering","question_text":"Without ORDER BY, which claim about result order is correct?","options":["Primary-key order is guaranteed","Insertion order is guaranteed","Alphabetic order is guaranteed","No order is guaranteed"],"correct_answer":"D","explanation":"Relational results are unordered unless ORDER BY is specified.","estimated_time_seconds":60,"difficulty":3,"option_a":"Primary-key order is guaranteed","option_b":"Insertion order is guaranteed","option_c":"Alphabetic order is guaranteed","option_d":"No order is guaranteed"},{"id":"db-2-1","category":"database_technical","subcategory":"Cardinality","question_text":"Which relationship lets one department contain many employees while each employee belongs to one department?","options":["One-to-many","One-to-one","Many-to-many","Self-reference"],"correct_answer":"A","explanation":"One-to-many models one parent row with multiple child rows.","estimated_time_seconds":60,"difficulty":1,"option_a":"One-to-many","option_b":"One-to-one","option_c":"Many-to-many","option_d":"Self-reference"},{"id":"db-2-2","category":"database_technical","subcategory":"Composite Keys","question_text":"What is a composite primary key?","options":["A key copied into two tables","A key formed from more than one column","An encrypted key","A nullable alternate key"],"correct_answer":"B","explanation":"A composite key uses multiple columns together to identify a row.","estimated_time_seconds":60,"difficulty":1,"option_a":"A key copied into two tables","option_b":"A key formed from more than one column","option_c":"An encrypted key","option_d":"A nullable alternate key"},{"id":"db-2-3","category":"database_technical","subcategory":"Candidate Keys","question_text":"What is a candidate key?","options":["Any indexed column","A foreign key awaiting approval","A minimal set of columns that uniquely identifies a row","A generated display label"],"correct_answer":"C","explanation":"A candidate key is both unique and minimal.","estimated_time_seconds":60,"difficulty":2,"option_a":"Any indexed column","option_b":"A foreign key awaiting approval","option_c":"A minimal set of columns that uniquely identifies a row","option_d":"A generated display label"},{"id":"db-2-4","category":"database_technical","subcategory":"Referential Actions","question_text":"What does ON DELETE CASCADE do?","options":["Prevents every parent deletion","Sets every child value to zero","Deletes the entire schema","Deletes dependent child rows when the referenced parent is deleted"],"correct_answer":"D","explanation":"CASCADE propagates the parent deletion to referencing rows.","estimated_time_seconds":60,"difficulty":2,"option_a":"Prevents every parent deletion","option_b":"Sets every child value to zero","option_c":"Deletes the entire schema","option_d":"Deletes dependent child rows when the referenced parent is deleted"},{"id":"db-2-5","category":"database_technical","subcategory":"Aggregation","question_text":"Which expression counts distinct department values?","options":["COUNT(DISTINCT department)","DISTINCT(COUNT department)","COUNT(UNIQUE department)","SUM(DISTINCT department)"],"correct_answer":"A","explanation":"COUNT with DISTINCT counts unique non-null values.","estimated_time_seconds":60,"difficulty":2,"option_a":"COUNT(DISTINCT department)","option_b":"DISTINCT(COUNT department)","option_c":"COUNT(UNIQUE department)","option_d":"SUM(DISTINCT department)"},{"id":"db-2-6","category":"database_technical","subcategory":"Grouping","question_text":"Which clause filters groups after aggregation?","options":["WHERE","HAVING","ORDER BY","LIMIT"],"correct_answer":"B","explanation":"HAVING evaluates conditions on grouped results.","estimated_time_seconds":60,"difficulty":2,"option_a":"WHERE","option_b":"HAVING","option_c":"ORDER BY","option_d":"LIMIT"},{"id":"db-2-7","category":"database_technical","subcategory":"Sorting","question_text":"How do you sort salary from highest to lowest?","options":["ORDER salary REVERSE","SORT salary DOWN","ORDER BY salary DESC","GROUP BY salary DESC"],"correct_answer":"C","explanation":"DESC requests descending order in ORDER BY.","estimated_time_seconds":60,"difficulty":2,"option_a":"ORDER salary REVERSE","option_b":"SORT salary DOWN","option_c":"ORDER BY salary DESC","option_d":"GROUP BY salary DESC"},{"id":"db-2-8","category":"database_technical","subcategory":"Transactions","question_text":"What does ROLLBACK do in an open transaction?","options":["Makes changes permanent","Creates an index","Locks the database forever","Discards uncommitted changes"],"correct_answer":"D","explanation":"ROLLBACK reverses the current transaction's uncommitted work.","estimated_time_seconds":60,"difficulty":3,"option_a":"Makes changes permanent","option_b":"Creates an index","option_c":"Locks the database forever","option_d":"Discards uncommitted changes"},{"id":"db-2-9","category":"database_technical","subcategory":"Transactions","question_text":"What does COMMIT do?","options":["Makes the current transaction's changes permanent","Removes the current table","Cancels the current query plan","Restores a backup"],"correct_answer":"A","explanation":"COMMIT completes a transaction and persists its changes.","estimated_time_seconds":60,"difficulty":3,"option_a":"Makes the current transaction's changes permanent","option_b":"Removes the current table","option_c":"Cancels the current query plan","option_d":"Restores a backup"},{"id":"db-2-10","category":"database_technical","subcategory":"Isolation","question_text":"What is a non-repeatable read?","options":["Reading a row with duplicate columns","Reading the same row twice and seeing different committed values","Running the same query on two databases","Reading without an index"],"correct_answer":"B","explanation":"Another committed transaction can change a row between two reads.","estimated_time_seconds":60,"difficulty":3,"option_a":"Reading a row with duplicate columns","option_b":"Reading the same row twice and seeing different committed values","option_c":"Running the same query on two databases","option_d":"Reading without an index"},{"id":"db-2-11","category":"database_technical","subcategory":"Indexes","question_text":"Why can too many indexes slow INSERT operations?","options":["Indexes disable transactions","Every index duplicates the database","Each relevant index must also be updated","Indexes force network calls"],"correct_answer":"C","explanation":"Writes maintain table data and each affected index.","estimated_time_seconds":60,"difficulty":1,"option_a":"Indexes disable transactions","option_b":"Every index duplicates the database","option_c":"Each relevant index must also be updated","option_d":"Indexes force network calls"},{"id":"db-2-12","category":"database_technical","subcategory":"Query Plans","question_text":"What does a query execution plan describe?","options":["The table's business purpose","A backup schedule","The user interface layout","How the database intends to execute a query"],"correct_answer":"D","explanation":"The plan describes operations such as scans, joins, and sorts.","estimated_time_seconds":60,"difficulty":1,"option_a":"The table's business purpose","option_b":"A backup schedule","option_c":"The user interface layout","option_d":"How the database intends to execute a query"},{"id":"db-2-13","category":"database_technical","subcategory":"Joins","question_text":"Which join returns all rows from both inputs, matching where possible?","options":["FULL OUTER JOIN","INNER JOIN","LEFT JOIN","CROSS JOIN"],"correct_answer":"A","explanation":"FULL OUTER JOIN preserves unmatched rows from both sides.","estimated_time_seconds":60,"difficulty":2,"option_a":"FULL OUTER JOIN","option_b":"INNER JOIN","option_c":"LEFT JOIN","option_d":"CROSS JOIN"},{"id":"db-2-14","category":"database_technical","subcategory":"Joins","question_text":"What does a CROSS JOIN produce?","options":["Only rows with equal keys","Every possible pair of rows from the two inputs","Only unmatched rows","A union of column names"],"correct_answer":"B","explanation":"A CROSS JOIN returns the Cartesian product.","estimated_time_seconds":60,"difficulty":2,"option_a":"Only rows with equal keys","option_b":"Every possible pair of rows from the two inputs","option_c":"Only unmatched rows","option_d":"A union of column names"},{"id":"db-2-15","category":"database_technical","subcategory":"Subqueries","question_text":"What must a scalar subquery return?","options":["Exactly four columns","Only Boolean values","At most one row and one column","An entire table"],"correct_answer":"C","explanation":"A scalar context expects a single value.","estimated_time_seconds":60,"difficulty":2,"option_a":"Exactly four columns","option_b":"Only Boolean values","option_c":"At most one row and one column","option_d":"An entire table"},{"id":"db-2-16","category":"database_technical","subcategory":"Constraints","question_text":"Which constraint prevents duplicate values in a column or column set?","options":["DEFAULT","CHECK","NOT NULL only","UNIQUE"],"correct_answer":"D","explanation":"UNIQUE enforces distinct non-null key combinations according to database semantics.","estimated_time_seconds":60,"difficulty":2,"option_a":"DEFAULT","option_b":"CHECK","option_c":"NOT NULL only","option_d":"UNIQUE"},{"id":"db-2-17","category":"database_technical","subcategory":"Constraints","question_text":"What does NOT NULL enforce?","options":["A column must contain a value for every row","A column must be unique","A table cannot be deleted","A query cannot return zero rows"],"correct_answer":"A","explanation":"NOT NULL rejects rows that omit a value for that column.","estimated_time_seconds":60,"difficulty":2,"option_a":"A column must contain a value for every row","option_b":"A column must be unique","option_c":"A table cannot be deleted","option_d":"A query cannot return zero rows"},{"id":"db-2-18","category":"database_technical","subcategory":"Views","question_text":"How does a materialized view differ from a standard view?","options":["It cannot contain a SELECT query","It stores query results that must be refreshed","It always updates each second","It bypasses every permission"],"correct_answer":"B","explanation":"A materialized view persists results instead of only storing a query definition.","estimated_time_seconds":60,"difficulty":3,"option_a":"It cannot contain a SELECT query","option_b":"It stores query results that must be refreshed","option_c":"It always updates each second","option_d":"It bypasses every permission"},{"id":"db-2-19","category":"database_technical","subcategory":"Normalization","question_text":"What does first normal form require of stored attribute values?","options":["Every table has two primary keys","Every column is numeric","Each field contains an atomic value rather than a repeating group","All tables contain the same columns"],"correct_answer":"C","explanation":"First normal form removes repeating groups and keeps values atomic for the model.","estimated_time_seconds":60,"difficulty":3,"option_a":"Every table has two primary keys","option_b":"Every column is numeric","option_c":"Each field contains an atomic value rather than a repeating group","option_d":"All tables contain the same columns"},{"id":"db-2-20","category":"database_technical","subcategory":"Set Operations","question_text":"When should UNION ALL be preferred over UNION?","options":["When rows must be joined by a key","When a table must be updated","When only one query is available","When duplicates should be retained and duplicate elimination is unnecessary"],"correct_answer":"D","explanation":"UNION ALL combines results without the cost or behavior of removing duplicates.","estimated_time_seconds":60,"difficulty":3,"option_a":"When rows must be joined by a key","option_b":"When a table must be updated","option_c":"When only one query is available","option_d":"When duplicates should be retained and duplicate elimination is unnecessary"}]$diagnostic$::jsonb) as x(id text,question_text text,category text,subcategory text,difficulty numeric,option_a text,option_b text,option_c text,option_d text,correct_answer char(1),explanation text,estimated_time_seconds integer) on conflict(id) do update set question_text=excluded.question_text,category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_answer=excluded.correct_answer,explanation=excluded.explanation,estimated_time_seconds=excluded.estimated_time_seconds,active=true;
